const f=document.createElement("iframe");f.title="SchichtLohn";this._f=f;
f.style.cssText="border:0;width:100%;height:calc(100vh - var(--header-height,56px) - 16px);min-height:600px;display:block;background:transparent";
f.setAttribute("allowtransparency","true");f.setAttribute("allow","camera; clipboard-read; clipboard-write");
f.addEventListener("load",()=>{this._themeKey=null;this._push()});f.srcdoc=SL_HTML;card.appendChild(f);
